using System.Windows;
using System.Windows.Controls;

namespace DzhiggaTV.App;

public sealed class ReleaseNotesWindow : Window
{
    private CancellationTokenSource? _checking;

    public ReleaseNotesWindow(Window owner)
    {
        Theme.Window(this);
        Owner = owner; Title = "DzhiggaTV · История версий"; ShowInTaskbar = false;
        Width = 610; Height = 620; MinWidth = 480; MinHeight = 360;
        MaxHeight = Math.Max(360, SystemParameters.WorkArea.Height - 60);
        WindowStartupLocation = WindowStartupLocation.CenterOwner;
        Closed += (_, _) => _checking?.Cancel();

        var root = new DockPanel { Margin = new(24) }; Content = root;
        var heading = new StackPanel { Margin = new(0, 0, 0, 18) };
        heading.Children.Add(new TextBlock { Text = "История версий", FontSize = 24, FontWeight = FontWeights.SemiBold });
        var current = new TextBlock { Text = $"Текущая версия — {App.DisplayVersion}", FontSize = 12, Margin = new(0, 7, 0, 0) };
        current.SetResourceReference(TextBlock.ForegroundProperty, "MutedBrush"); heading.Children.Add(current);
        DockPanel.SetDock(heading, Dock.Top); root.Children.Add(heading);

        var footer = new Grid { Margin = new(0, 16, 0, 0) };
        footer.ColumnDefinitions.Add(new()); footer.ColumnDefinitions.Add(new() { Width = GridLength.Auto });
        var status = new TextBlock { FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new(3, 0, 14, 0), VerticalAlignment = VerticalAlignment.Center, Visibility = Visibility.Collapsed };
        status.SetResourceReference(TextBlock.ForegroundProperty, "MutedBrush");
        System.Windows.Automation.AutomationProperties.SetName(status, "Результат проверки обновлений");
        System.Windows.Automation.AutomationProperties.SetLiveSetting(status, System.Windows.Automation.AutomationLiveSetting.Polite);
        footer.Children.Add(status);
        var buttons = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
        Grid.SetColumn(buttons, 1);
        var check = new Button { Content = "Проверить обновления", MinWidth = 190 };
        check.SetResourceReference(BorderBrushProperty, "AccentBrush");
        System.Windows.Automation.AutomationProperties.SetName(check, "Проверить обновления");
        check.Click += async (_, _) =>
        {
            if (owner is not MainWindow main) return;
            using var lifetime = new CancellationTokenSource(); _checking = lifetime;
            check.IsEnabled = false; check.Content = "Проверяем…";
            status.Text = "Проверяем обновления…"; status.Visibility = Visibility.Visible;
            try
            {
                await main.Updates.CheckAsync(true, lifetime.Token);
                if (!IsVisible || lifetime.IsCancellationRequested) return;
                if (main.Updates.LastError is { } error) status.Text = error;
                else if (!main.Updates.HasUpdate) status.Text = "Версия актуальна. Новых версий не найдено.";
                else
                {
                    status.Visibility = Visibility.Collapsed;
                    await main.ShowUpdateDialogAsync(this, false);
                }
            }
            catch (OperationCanceledException) when (lifetime.IsCancellationRequested) { }
            finally
            {
                _checking = null;
                if (IsVisible) { check.IsEnabled = true; check.Content = "Проверить обновления"; }
            }
        };
        var close = new Button { Content = "Закрыть", IsCancel = true, IsDefault = true };
        buttons.Children.Add(check); buttons.Children.Add(close); footer.Children.Add(buttons);
        DockPanel.SetDock(footer, Dock.Bottom); root.Children.Add(footer);
        var notes = new StackPanel();
        (string Version, string Summary)[] releases =
        [
            ("1.5.10", "Архив продолжает воспроизведение после окончания передачи. Название, описание и следующие передачи обновляются по времени записи без остановки видео. Когда заканчивается загруженный участок архива, автоматически открывается продолжение; у самой границы прямого эфира просмотр продолжается в эфире. Пробелы в телепрограмме не прерывают просмотр; выбранная вручную карточка истории сохраняется при смене передачи в видео."),
            ("1.5.9", "На каналах без архива кнопка открытия телепрограммы перенесена в верхний правый угол карточки «Сейчас в эфире», рядом с её заголовком. Новая подпись — «Телепрограмма →». На каналах с архивом эта кнопка по-прежнему скрыта."),
            ("1.5.8", "Изменение размера мини-плеера сохраняет соотношение сторон видео при перетаскивании любого края или угла. Учитываются рамка окна, масштаб Windows, минимальный размер, форматы 16:9 и 4:3 и пропорции самого потока. При открытии мини-плеера и смене формата ширина и высота также согласуются с видео; выбранный размер сохраняется."),
            ("1.5.7", "Открытая «Информация о потоке» закрывается обычным щелчком левой кнопки по видео в основном, полноэкранном и мини-режиме. Повторно открыть её можно через меню плеера или клавишей I."),
            ("1.5.6", "Мини-плеер можно изменять за любой край или угол окна: видео и управление больше не перекрывают область изменения размера. Начальный размер уменьшен до 440 × 255, минимальный — до 320 × 196. Выбранные размер и положение сохраняются при возврате в главное окно и закрытии приложения. Старый стандартный размер заменяется новым компактным; настройки собственного размера сохраняются."),
            ("1.5.5", "В меню плеера оставлены только звуковая дорожка, соотношение сторон и информация о потоке. Это же меню открывается правой кнопкой мыши по видео в обычном, полноэкранном и мини-режиме. Текущая звуковая дорожка и соотношение сторон отмечаются галочкой. Техническая статистика переименована в «Информация о потоке»; клавиша I сохранена. В отдельном окне телепрограммы расписание можно листать, зажав левую кнопку мыши и перетаскивая его вправо или влево. Названия каналов остаются на месте; жест не переключает видео, щелчок и двойной щелчок сохраняют свои действия."),
            ("1.5.4", "Нажатие «С начала передачи» в плеере запускает текущую передачу с начала. Вместо отдельного выбора даты и времени открывается телепрограмма; дублирующая кнопка «Программа» убрана из карточки каналов с архивом. Добавлен контроль остановки потока, ограниченное автоматическое восстановление и сохранение позиции архива. При загрузке, буферизации и зависании в центре видео появляется анимированный индикатор; после неудачного восстановления можно повторить подключение. Пауза и обычная перемотка не считаются зависанием, а смена канала отменяет старые попытки."),
            ("1.5.3", "Подсветка кнопок истории передач больше не остаётся после клика и ухода курсора. При навигации клавиатурой фокус обозначен отдельной рамкой. Кнопка «К просмотру» переименована в «В прямой эфир»: возвращает актуальные карточки и, если воспроизводится архив, переключает на прямую трансляцию."),
            ("1.5.2", "Исправлена перемотка архива вперёд после перехода назад: вне загруженного участка запись открывается с выбранного времени. Увеличены бегунок и область нажатия; при наведении и перетаскивании показаны точные дата и время перехода. Сохраняются пауза и громкость. Переход к предыдущим передачам стал заметнее: кнопка «Ранее» с крупной стрелкой, рамкой и подсветкой находится справа над названием, а ссылка на телепрограмму — в строке времени. Размер карточек сохранён."),
            ("1.5.1", "В основном списке каналы с архивом отмечены значком ↶ и глубиной в днях. В карточках под видео можно листать предыдущие передачи стрелками, читать описания и запускать выбранную запись кнопкой «Смотреть». Просмотр истории не переключает видео; «К просмотру» возвращает информацию о воспроизводимой передаче. Учитываются доступная глубина архива, даты и смена канала."),
            ("1.5.0", "Просмотр архива телеканалов с учётом доступной глубины в плейлисте: выбор прошедших передач в телепрограмме и просмотр текущей передачи с начала. В основном плеере появились шкала перемотки, выбор даты и времени и возврат в прямой эфир. Описание и следующие передачи соответствуют просматриваемой записи. Поддерживаются tvg-rec, timeshift и параметры catchup. Мини-плеер без заголовка: кнопки закрытия и закрепления поверх окон появляются при движении мыши. В полноэкранном режиме управление и описание не реагируют на небольшое дрожание курсора. Цвет и анимация иконок работают при наведении даже без фокуса приложения."),
            ("1.2.15", "В нижней панели «Мультиэкрана» вместо длинного расписания показаны три карточки: «Сейчас в эфире», «Далее» и «Затем». Описания открываются рядом с «Подробнее», как в основном плеере. Расширенное расписание в боковой панели сохранено."),
            ("1.2.14", "Ширина карточки описания в полном экране увеличена до 35% — в основном плеере и при разворачивании одного канала «Мультиэкрана»."),
            ("1.2.13", "В «Мультиэкране» видео можно перетаскивать прямо между ячейками: каналы меняются местами без переподключения и смены звука. Двойной щелчок разворачивает один канал на весь экран; повторный двойной щелчок или Esc возвращает сетку, остальные трансляции продолжаются. Боковая телепрограмма показывает до 24 следующих передач с прокруткой. Полноэкранное описание оформлено компактной карточкой слева, не шире четверти экрана; сведения о фильме отделены от описания."),
            ("1.2.12", "Уменьшены расход памяти на логотипы и фоновая нагрузка интерфейса и видеодвижка. Логотипы загружаются с учётом размера и DPI экрана, общий кэш ограничен. Телепрограмма видимых каналов читается одним согласованным снимком базы; при импорте XMLTV повторно используется текстовый буфер. Добавлена фоновая очистка завершённых старых обновлений с сохранением текущих и новых пакетов и работающего установщика. Установщик сжат без удаления компонентов, кодеков или изменения качества видео."),
            ("1.2.11", "Мультиэкран автоматически перестраивается под оставшиеся каналы: пустые ячейки не занимают место, для двух и трёх видео выбирается раскладка с большей площадью изображения и сохранением пропорций. Режим четырёх каналов сохранён. Главное окно запускается развёрнутым. Заголовки установщика и отдельного окна обновления оформлены в тёмном цвете. Окно обновления стало компактнее: убраны нижний текстовый блок и кнопка «Открыть плеер», состояние показывается над полосой."),
            ("1.2.10", "Нижняя строка главного окна с количеством каналов и подсказкой F11 стала вдвое ниже: 16 вместо 32. Убраны лишние вертикальные отступы, текст выровнен по центру. Освободившееся место передано области просмотра. Компактная высота сохраняется после возврата из полного экрана и мини-плеера."),
            ("1.2.9", "При выборе категории основной список каналов, телепрограмма и список выбора «Мультиэкрана» начинаются сверху. В телепрограмме выбор плейлиста и сброс фильтров также возвращают к началу списка. Экраны «Мультиэкрана» подстраиваются под пропорции своих трансляций, включая каналы 4:3 и анаморфное видео. Свободное место справа или снизу занимает телепрограмма канала со звуком: текущая передача, описание и две следующие. Щелчок по шкале громкости сразу перемещает бегунок в выбранную точку — в основном плеере и мультиэкране."),
            ("1.2.8", "«Каналы» получили янтарный телевизор, «Телепрограмма» — фиолетовый лист расписания с часами; зелёный «Мультиэкран» сохранён. Иконки больше не остаются цветными после клика и закрытия окна. Сообщение об актуальной версии перенесено слева от кнопки. В выборе мультиэкрана исправлено обрезанное поле числа экранов и добавлена загрузка логотипов видимых каналов при открытии, поиске и прокрутке. Переносимая карточка стала квадратной и плавно вырастает до размера ячейки."),
            ("1.2.7", "При ручной проверке без новых выпусков рядом с кнопкой появляется надпись «Версия актуальна. Новых версий не найдено», без отдельного окна. В выборе каналов «Мультиэкрана» карточка с логотипом следует за мышью, место назначения плавно подсвечивается, а перенос завершается мягкой анимацией. Логотипы в схеме увеличены, названия стали крупнее и полужирными. Учитывается настройка сокращения анимаций."),
            ("1.2.6", "Выбор каналов «Мультиэкрана» дополнен схемой: перетаскивайте каналы на нужные места, меняйте экраны местами или заменяйте канал. Галочки заполняют свободные места, кнопка «Сброс» снимает весь выбор. Расположение и пустые ячейки сохраняются. Одновременно можно смотреть до четырёх каналов в сетке 2 × 2; прежние большие наборы автоматически сокращаются."),
            ("1.2.5", "«Мультиэкран» открывается с тем же количеством экранов, которое было при последнем использовании. Текущий канал основного плеера занимает первое место и получает звук: если его не было в наборе, он заменяет прежний первый канал. При первом запуске с текущим каналом открывается один экран без автоматического окна выбора; добавлять и убирать каналы можно кнопкой «Выбрать каналы»."),
            ("1.2.4", "При открытии «Мультиэкрана» текущий канал основного плеера становится первым в сетке и выбирается источником звука. Если его не было в сохранённом наборе, он добавляется автоматически; при девяти заполненных местах заменяет последний канал. При повторном открытии приоритет получает канал, который сейчас включён в основном плеере. Из подсказки кнопки убрано лишнее пояснение — оставлено только название «Мультиэкран»."),
            ("1.2.3", "«Спортивный вечер» переименован в «Мультиэкран»: новое название используется в меню, заголовках окон, выборе каналов и подсказках."),
            ("1.2.2", "Во время «Спортивного вечера» основной плеер продолжает трансляцию без паузы, с выключенным звуком. При возврате восстанавливается звук текущего эфира без накопленной из-за паузы задержки."),
            ("1.2.1", "Иконка «Спортивного вечера» приведена к общему стилю навигации: четыре скруглённых экрана, приглушённый контур в покое и зелёно-бирюзовый цвет при наведении. Используются те же плавные увеличение и поворот, подсветка с клавиатуры и учёт настройки уменьшения движения, что у остальных значков."),
            ("1.2.0", "Добавлен «Спортивный вечер»: одновременный просмотр до девяти каналов в сетке, выбор каналов с поиском и категориями, общий регулятор громкости и звук только с выбранного канала. Источник звука переключается кнопкой или щелчком по видео. Состав каналов и выбранный источник сохраняются; доступны полный экран, удаление и переподключение отдельных трансляций. Основной плеер приостанавливается до закрытия режима."),
            ("1.1.2", "Исправлено заполнение карточек «Сейчас в эфире», «Далее» и «Затем» при запуске и восстановлении последнего канала. Сохранённая программа показывается до подключения к трансляции, не ожидая фонового обновления EPG и записи настроек. Поздняя подгрузка программы сразу обновляет карточки."),
            ("1.1.1", "Верхняя панель стала ниже примерно на 37%: уменьшены логотип, название и отступы, номер версии расположен в одну строку. Видеоплееру доступно больше места; компактная панель сохраняется после выхода из полного экрана и мини-плеера."),
            ("1.1.0", "В «Избранном» убраны поиск и выбор категории: фильтры из других разделов не влияют на избранные каналы, Ctrl+F не активирует поиск. Если нет данных о времени окончания текущей передачи, строка «До конца осталось» полностью скрывается. Из бокового меню убраны лишние подписи."),
            ("1.0.34", "Надпись «До конца осталось» стала менее заметной: приглушённый цвет и обычное начертание. Оставшееся время показывается с точностью до минут, без секунд."),
            ("1.0.33", "Повторный клик по звёздочке выключает избранное даже под указателем мыши и сразу убирает канал из списка избранного. В полосе плеера убраны кнопки предыдущего просмотренного канала и списка каналов; по центру показано время до конца текущей передачи с обновлением каждую секунду."),
            ("1.0.32", "У каналов используются те же звёздочки избранного, что в левом меню, вдвое меньшего размера: с цветом и анимацией при наведении, цветным состоянием избранного и прежней областью нажатия. Все полосы прокрутки стали ещё на 50% уже. Из описаний убран заголовок «Сведения»."),
            ("1.0.31", "«Подробнее» у «Сейчас в эфире», «Далее» и «Затем» открывает одинаковые всплывающие окна рядом с кнопкой, с возможностью перекрытия края видео. Год, страна и жанр выделены отдельным блоком, сюжет сохранён с абзацами, актёры и создатели отделены линией. Такое же оформление используется в телепрограмме; в карточке текущей передачи показан сюжет без служебного вступления."),
            ("1.0.30", "Добавлены номера каналов слева от логотипов в основном списке и в списке поверх видео. Нумерация общая для библиотеки: при поиске, выборе категории и переходе в избранное номер канала сохраняется."),
            ("1.0.29", "В полном экране увеличена область описания с прокруткой: сюжет отделён от года, жанра, страны и сведений о фильме. Полосы прокрутки стали тоньше на 30%. Описания «Далее» и «Затем» открываются рядом со своей кнопкой «Подробнее», поверх нижнего края видео."),
            ("1.0.28", "Текущая передача выделена бирюзовой рамкой, более выразительным фоном и индикатором эфира; размер карточки сохранён. Справа показаны две следующие передачи одна под другой, с названием и временем. Полные описания доступны по «Подробнее», без перекрытия видео и списка каналов."),
            ("1.0.27", "Убрано смещение строк каналов при наведении: рамка меняет только цвет. Поиск в списке каналов находит также текущие и предстоящие передачи во всей загруженной телепрограмме. В результатах видны название передачи и время начала; категории и избранное учитываются."),
            ("1.0.26", "В полноэкранную панель добавлено описание текущей передачи. Канал выделен цветом, текст оформлен с удобными отступами и ограничен двумя–тремя строками без прокрутки. При отсутствии описания пустое место не показывается; вся панель скрывается вместе с управлением."),
            ("1.0.25", "При открытии телепрограммы текущий канал располагается по центру списка. Кнопка «Сейчас» также возвращает к нему с центрированием. У начала и конца списка прокрутка ограничивается его границами."),
            ("1.0.24", "Раскрытое описание остаётся открытым при переходе с «Подробнее» на сам текст. Его можно прокручивать колёсиком и полосой прокрутки. Блок закрывается после ухода курсора с кнопки и описания."),
            ("1.0.23", "В полном экране над кнопками управления показываются название канала, текущая передача, время эфира и прогресс просмотра. Информация появляется и исчезает вместе с управлением; при отсутствии телепрограммы дополнительный блок скрыт."),
            ("1.0.22", "Часы над видео увеличены до размера названия канала: 22, полужирное начертание."),
            ("1.0.21", "Кнопка «Подробнее» появляется только у обрезанного описания текущей или следующей передачи. Наведение на кнопку показывает полный текст под видео, уход с неё сразу возвращает карточки. Длинный текст прокручивается колёсиком над кнопкой; видео и список каналов остаются открытыми."),
            ("1.0.20", "Полное описание передачи раскрывается на месте карточек под видео. Видео и список каналов остаются полностью открытыми, размер видеоплеера не меняется. В раскрытом блоке можно переключаться между текущей и следующей передачей; длинный текст доступен целиком с прокруткой."),
            ("1.0.19", "Развёрнутое окно учитывает панель задач текущего монитора. Канал, включённый из телепрограммы, выделяется в основном списке. Добавлены фильтры плейлиста и категории, логотипы каналов в телепрограмме. При наведении на текущую или следующую передачу полное описание появляется сбоку и не перекрывает видео. Новые иконки навигации плавно окрашиваются и анимируются при наведении."),
            ("1.0.18", "Переработана телепрограмма: открытие на текущем эфире, движущаяся пунктирная линия точного времени и неподвижные названия каналов. Один щелчок открывает полное описание, двойной переключает канал. Компактная панель выбора дня, поиск и быстрый возврат к «Сейчас». Ускорена загрузка больших библиотек."),
            ("1.0.17", "В нижней строке оставлены только количество каналов в библиотеке и подсказка «F11 — полный экран». Убраны лишние служебные надписи."),
            ("1.0.16", "Добавлены дельта-обновления: плеер скачивает только изменённые файлы и использует уже установленный видеодвижок и .NET. Пакеты создаются автоматически на GitHub. Перед установкой все файлы проверяются; если небольшой пакет не подходит, загрузится полный установщик. Переход на эту версию требует одного полного обновления."),
            ("1.0.15", "Карточки текущей и следующей передачи стали компактнее: короткое описание в две строки с многоточием, без внутренней прокрутки. Длинные названия аккуратно сокращаются, больше места остаётся для видео."),
            ("1.0.14", "В карточках текущей и следующей передачи показаны подробные описания из телепрограммы. Длинный текст прокручивается, размер карточек подстраивается под окно и наличие описания."),
            ("1.0.13", "Обновление через GitHub Releases: подсветка новой версии, описание изменений, загрузка с проверкой и автоматический перезапуск. В истории версий — ручная проверка обновлений."),
            ("1.0.12", "В верхней панели добавлены видимые кнопки сворачивания, разворачивания / восстановления и закрытия окна."),
            ("1.0.11", "Убрана кнопка сортировки «Плейлист». Полоса прокрутки стала шире, бегунок — крупнее и заметнее при наведении."),
            ("1.0.10", "История изменений открывается по нажатию на номер версии."),
            ("1.0.9", "Убран информационный блок EPG.ONE над поиском каналов."),
            ("1.0.8", "Убраны лишние кнопки из верхней панели."),
            ("1.0.7", "Новый логотип программы, тёмный заголовок окна и логотип текущего канала."),
            ("1.0.6", "Исправлено меню плеера и обновлено оформление номера версии."),
            ("1.0.5", "Номер версии появился рядом с названием приложения."),
            ("1.0.4", "Упрощена навигация; категории открываются по клику, боковая панель свёрнута при запуске."),
            ("1.0.3", "Компактное управление при наведении; убрана верхняя плашка внутри видео."),
            ("1.0.2", "Убраны буквы под логотипами и исправлено закрытие приложения."),
            ("1.0.1", "Исправлена загрузка телепрограммы и логотипов EPG.ONE."),
            ("1.0.0", "Первый выпуск: IPTV, телепрограмма, избранное, история и мини-плеер.")
        ];
        foreach (var (version, summary) in releases)
        {
            var row = new Grid();
            row.ColumnDefinitions.Add(new() { Width = new(76) }); row.ColumnDefinitions.Add(new());
            var versionLabel = App.FormatVersion(Version.Parse(version));
            var label = new TextBlock { Text = versionLabel, FontWeight = FontWeights.SemiBold, FontSize = 13, Margin = new(0, 1, 10, 0) };
            label.SetResourceReference(TextBlock.ForegroundProperty, "AccentBrush"); row.Children.Add(label);
            var text = new TextBlock { Text = summary, TextWrapping = TextWrapping.Wrap, FontSize = 13, LineHeight = 20 };
            Grid.SetColumn(text, 1); row.Children.Add(text);
            var card = new Border { Child = row, Padding = new(12, 10, 12, 10), CornerRadius = new(7), Margin = new(0, 0, 5, 4) };
            if (versionLabel == App.DisplayVersion) card.SetResourceReference(BackgroundProperty, "CardBrush");
            notes.Children.Add(card);
        }
        root.Children.Add(new ScrollViewer { Content = notes, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled });
    }
}
